import { useMigrations } from 'drizzle-orm/expo-sqlite/migrator';
import { db } from './client';
// Generated by `npm run db:generate` (drizzle-kit). See migrations.d.ts.
import migrations from './migrations/migrations';

/**
 * Applies pending SQLite migrations at startup.
 * Returns { success, error } — the root layout gates rendering on success.
 */
export function useDrizzleMigrations() {
  return useMigrations(db, migrations);
}
